style.css:
/* === CUSTOM FACEBOOK BACKGROUND === */

/* Page background */
body {
    background-image: url("https://static.wikia.nocookie.net/library-of-ruina/images/0/03/HokmaFloorBattleStage.png/revision/latest/scale-to-width-down/1000?cb=20201128043544") !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-position: center center !important;
}

/* Make main content slightly transparent (optional but looks nice) */
div[role="main"],
div[data-pagelet],
div[data-testid="fbfeed_story"] {
    background-color: rgba(255, 255, 255, 0.85) !important;
    border-radius: 12px;
}
